  const records=rows().flatMap(d=>(d.readings.length?d.readings:[null]).map(reading=>[d.date,patients[current].name,d.submissions,d.missing?'unknown':d.symptoms.join('; ')||'none reported',reading?.time??'',reading?.fev??'',reading?.quality??'no reading',d.doses,2,d.zone,d.missing?'':d.rescue,d.missing?'':d.school]));
