function recentReviewSignals(key){
  const days=dataset(key),thisWeek=days.slice(-7),lastWeek=days.slice(-14,-7),symptomDays=thisWeek.filter(d=>!d.missing&&d.symptoms.length).length,lastSymptomDays=lastWeek.filter(d=>!d.missing&&d.symptoms.length).length,signals=[];
  if(symptomDays>=3)signals.push({kind:'symptom',text:`Symptoms on ${symptomDays} of 7 days`});
  else if(symptomDays>lastSymptomDays)signals.push({kind:'symptom',text:`${symptomDays-lastSymptomDays} more symptom day${symptomDays-lastSymptomDays===1?'':'s'} than last week`});
  const currentF=median(thisWeek.map(bestAccepted).filter(Boolean).map(x=>x.fev)),previousF=median(lastWeek.map(bestAccepted).filter(Boolean).map(x=>x.fev));
  if(currentF!==null&&previousF!==null&&currentF<previousF)signals.push({kind:'fev1',text:`FEV1 weekly median fell (${currentF.toFixed(2)} vs ${previousF.toFixed(2)} L)`});
  if(thisWeek.slice(-3).length===3&&thisWeek.slice(-3).every(d=>d.missing))signals.push({kind:'gap',text:'No tracker entry for 3 days'});
  return {signals,symptomDays,missing:thisWeek.filter(d=>d.missing).length,score:signals.length*10+symptomDays};
}
